import assert from 'node:assert/strict';

const names = ['kim','lee','park','jung','choi'];
const rnd = (n) => Math.floor(Math.random() * n);
const lowerKey = () => Array.from({length: 1 + rnd(8)}, () => String.fromCharCode(97 + rnd(26))).join('');
let checks = 0;
const eq = (a, b, label) => { assert.deepStrictEqual(b, a, label); checks++; };

// doubled: examples + random objects with 0-5 lowercase keys, ints in -5..99
const dExamples = [{"jung":43,"park":16}, {}];
for (const s of dExamples) eq(orig.doubled(s), next.doubled(s), 'doubled ex');
for (let i = 0; i < 20000; i++) {
  const o = {}; const k = rnd(6);
  for (let j = 0; j < k; j++) o[lowerKey()] = -5 + rnd(105);
  eq(orig.doubled(o), next.doubled(o), 'doubled rnd');
}

// byNameKey
const rowsEx = [[], [{"id":9,"name":"kim","age":34},{"id":3,"name":"park","age":57},{"id":2,"name":"jung","age":58},{"id":1,"name":"lee","age":47},{"id":5,"name":"park","age":30},{"id":3,"name":"lee","age":40},{"id":0,"name":"park","age":19},{"id":0,"name":"lee","age":24},{"id":0,"name":"kim","age":51},{"id":4,"name":"park","age":45},{"id":7,"name":"kim","age":37},{"id":9,"name":"lee","age":51}]];
for (const r of rowsEx) eq(orig.byNameKey(r), next.byNameKey(r), 'byNameKey ex');
for (let i = 0; i < 20000; i++) {
  const rows = Array.from({length: rnd(13)}, () => ({id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43)}));
  eq(orig.byNameKey(rows), next.byNameKey(rows), 'byNameKey rnd');
}

// toLookup
const pEx = [[["kim",57],["jung",57],["kim",72],["choi",59],["jung",53],["lee",28]], [["kim",35],["lee",1],["jung",41],["park",11],["jung",39],["jung",92]]];
for (const p of pEx) eq(orig.toLookup(p), next.toLookup(p), 'toLookup ex');
for (let i = 0; i < 20000; i++) {
  const pairs = Array.from({length: rnd(9)}, () => [names[rnd(5)], rnd(100)]);
  eq(orig.toLookup(pairs), next.toLookup(pairs), 'toLookup rnd');
}
console.log('all equal, checks =', checks);
console.log('sample byNameKey', JSON.stringify(next.byNameKey(rowsEx[1])));
console.log('sample toLookup', JSON.stringify(next.toLookup(pEx[0])));
EOF
